{
  "tools": [
    {
      "name": "github_get_commit_check_runs",
      "integration": "github",
      "category": "pull_requests",
      "description": "Get all check runs (CI/CD status checks) for a commit SHA in a GitHub repository.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "workspace": {
            "type": "string",
            "description": "The GitHub owner/organization name"
          },
          "repository": {
            "type": "string",
            "description": "The GitHub repository name"
          },
          "commitSha": {
            "type": "string",
            "description": "The commit SHA to get check runs for"
          }
        },
        "required": [
          "workspace",
          "repository",
          "commitSha"
        ]
      }
    }

arguments.command:
timeout 90 dmtools github_get_commit_check_runs --workspace IstiN --repository flutter_agent_harness --commitSha 7da365d0a3f10c62b6f554d9828e2706a70ef067 2>&1 | python3 -c "
import json,sys
d=json.load(sys.stdin)
runs=d if isinstance(d,list) else d.get('check_runs') or d.get('data') or d
try:
    for r in runs:
        print(r.get('name'), '=>', r.get('conclusion') or r.get('status'))
except Exception as e:
    print('raw:', json.dumps(d)[:800])
" 2>&1 | head -30

